import random, collections, itertools, math, sys, time
n=24
parts=[list(range(0,8)), list(range(8,16)), list(range(16,24))]
candidates=[]
for a in range(3):
    for b in range(a+1,3):
        for u in parts[a]:
            for v in parts[b]:
                candidates.append((u,v))

def dist_leq(adj,u,v,L=5):
    # shortest path length <=L?
    if u==v: return 0
    seen={u}; frontier=[u]
    for d in range(1,L+1):
        nf=[]
        for x in frontier:
            for y in adj[x]:
                if y==v: return d
                if y not in seen:
                    seen.add(y); nf.append(y)
        frontier=nf
        if not frontier: break
    return None

def greedy(seed):
    rng=random.Random(seed)
    adj=[set() for _ in range(n)]
    edges=[]
    cand=candidates[:]
    # Maybe random order weighted choose allowed until stuck
    while True:
        allowed=[]
        for e in cand:
            u,v=e
            if dist_leq(adj,u,v,5) is None:
                allowed.append(e)
        if not allowed: break
        # choose edge with heuristic? random
        e=rng.choice(allowed)
        u,v=e
        adj[u].add(v); adj[v].add(u); edges.append(e); cand.remove(e)
        if len(edges)>=29:
            return edges
    return edges
